	@Test
	public void everyParallelKernelDeclineIsOneTheInterpretedEngineAlsoMakes() {
		Set<String> observed = new TreeSet<>();
		for (String query : CORPUS) {
			// several rounds: the earliest ones legitimately decline while shapes compile, and later ones expose the
			// steady-state reasons that actually matter
			for (int round = 0; round < 12; round++) {
				observed.addAll(parallelKernelDeclines(query));
			}
		}

		List<String> unjustified = new ArrayList<>();
		for (String reason : observed) {
			if (!ARBITRATION_OUTCOMES.contains(reason) && !PARITY_LEDGER.containsKey(ledgerKey(reason))) {
				unjustified.add(reason);
			}
		}
		assertThat(unjustified)
				.as("every parallel kernel decline must be one the interpreted parallel engine also makes; add an entry"
						+ " to PARITY_LEDGER with the justification, or close the gap. Observed reasons: " + observed)
				.isEmpty();
	}

	/**
	 * Reasons carry dynamic detail after a marker character ({@code unmergeable-aggregate-kind-7},
	 * {@code root-scan-unplannable-<exception>}); the ledger is keyed on the stable prefix.
	 */
	private static String ledgerKey(String reason) {
		if (PARITY_LEDGER.containsKey(reason)) {
			return reason;
		}
		for (String key : PARITY_LEDGER.keySet()) {
			if (reason.startsWith(key)) {
				return key;
			}
		}
		return reason;
	}

	private Set<String> parallelKernelDeclines(String query) {
		String rendered = findMetric(explain(query), STRATEGY_DECLINES_METRIC);
		Set<String> reasons = new LinkedHashSet<>();
		if (rendered == null) {
			return reasons;
		}
		for (String entry : rendered.split("[,;\\s]+")) {
			int colon = entry.indexOf(':');
			if (colon < 0) {
				continue;
			}
			String strategy = entry.substring(0, colon);
			if ("irKernelParallel".equals(strategy) || "irAggregateParallel".equals(strategy)) {
				reasons.add(entry.substring(colon + 1));
			}
		}
		return reasons;
	}

	private GenericPlanNode explain(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return conn.prepareTupleQuery(query).explain(Explanation.Level.Telemetry).toGenericPlanNode();
		}
	}

	private static String findMetric(GenericPlanNode node, String metricName) {
		if (node == null) {
			return null;
		}
		String value = node.getStringMetricActual(metricName);
		if (value != null) {
			return value;
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				String found = findMetric(child, metricName);
				if (found != null) {
					return found;
				}
			}
		}
		return null;
	}
